import{_ as e}from"./chunks/ark_v6s_front.Bnt4MIDz.js";import{_ as a,o as r,c as o,al as l}from"./chunks/framework.7vp1BMOE.js";const b=JSON.parse('{"title":"ARK Electronics ARKV6S","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/ark_v6s.md","filePath":"uk/flight_controller/ark_v6s.md"}'),i={name:"uk/flight_controller/ark_v6s.md"};function s(n,t,d,h,c,u){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="ark-electronics-arkv6s" tabindex="-1">ARK Electronics ARKV6S <a class="header-anchor" href="#ark-electronics-arkv6s" aria-label="Permalink to &quot;ARK Electronics ARKV6S&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://arkelectron.com/contact-us/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The USA-built <a href="https://arkelectron.gitbook.io/ark-documentation/flight-controllers/arkv6s" target="_blank" rel="noreferrer">ARKV6S</a> flight controller is a low-cost, single-IMU variant of the <a href="./../flight_controller/ark_v6x">ARKV6X</a>, based on the <a href="https://github.com/pixhawk/Pixhawk-Standards" target="_blank" rel="noreferrer">FMUV6X and Pixhawk Autopilot Bus open source standards</a>.</p><p>The Pixhawk Autopilot Bus (PAB) form factor enables the ARKV6S to be used on any <a href="./../flight_controller/pixhawk_autopilot_bus">PAB-compatible carrier board</a>, such as the <a href="./../flight_controller/ark_pab">ARK Pixhawk Autopilot Bus Carrier</a>.</p><p><img src="'+e+'" alt="ARKV6S Main Photo"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="store" tabindex="-1">Where To Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where To Buy {#store}&quot;">​</a></h2><p>Order From <a href="https://arkelectron.com/product/arkv6s-flight-controller/" target="_blank" rel="noreferrer">Ark Electronics</a> (US)</p><h2 id="датчики" tabindex="-1">Датчики <a class="header-anchor" href="#датчики" aria-label="Permalink to &quot;Датчики&quot;">​</a></h2><ul><li><a href="https://www.invensense.tdk.com/en-us/products/6-axis/iim-42653" target="_blank" rel="noreferrer">Invensense IIM-42653 Industrial IMU</a></li><li><a href="https://www.bosch-sensortec.com/en/products/environmental-sensors/pressure-sensors/bmp390/" target="_blank" rel="noreferrer">Bosch BMP390 Barometer</a></li><li><a href="https://www.st.com/en/mems-and-sensors/iis2mdc.html" target="_blank" rel="noreferrer">ST IIS2MDC Magnetometer</a></li></ul><h2 id="мікропроцесор" tabindex="-1">Мікропроцесор <a class="header-anchor" href="#мікропроцесор" aria-label="Permalink to &quot;Мікропроцесор&quot;">​</a></h2><ul><li><a href="https://www.st.com/en/microcontrollers-microprocessors/stm32h743ii.html" target="_blank" rel="noreferrer">STM32H743IIK6 MCU</a><ul><li>480MHz</li><li>2MB Flash</li><li>1MB RAM</li></ul></li></ul><h2 id="інші-характеристики" tabindex="-1">Інші характеристики <a class="header-anchor" href="#інші-характеристики" aria-label="Permalink to &quot;Інші характеристики&quot;">​</a></h2><ul><li>FRAM</li><li><a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-010%20Pixhawk%20Autopilot%20Bus%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Autopilot Bus (PAB) Form Factor</a></li><li>LED індикатори</li><li>Слот MicroSD</li><li>USA Built</li><li>Розроблений з нагрівачем потужністю 1 Вт. Підтримує датчики в теплі в екстремальних умовах</li></ul><h2 id="вимоги-до-живлення" tabindex="-1">Вимоги до живлення <a class="header-anchor" href="#вимоги-до-живлення" aria-label="Permalink to &quot;Вимоги до живлення&quot;">​</a></h2><ul><li>5V</li><li>500 мА <ul><li>300 мА для основної системи</li><li>200 мА для нагрівача</li></ul></li></ul><h2 id="додаткова-інформація" tabindex="-1">Додаткова інформація <a class="header-anchor" href="#додаткова-інформація" aria-label="Permalink to &quot;Додаткова інформація&quot;">​</a></h2><ul><li>Вага: 5.0 g</li><li>Розміри: 3,6 x 2,9 x 0,5 см</li></ul><h2 id="схема-розташування-виводів" tabindex="-1">Схема розташування виводів <a class="header-anchor" href="#схема-розташування-виводів" aria-label="Permalink to &quot;Схема розташування виводів&quot;">​</a></h2><p>For pinout of the ARKV6S see the <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-010%20Pixhawk%20Autopilot%20Bus%20Standard.pdf" target="_blank" rel="noreferrer">DS-10 Pixhawk Autopilot Bus Standard</a></p><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM3</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>Debug Console</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>UART4 &amp; I2C</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TELEM2</td></tr><tr><td>USART6</td><td>/dev/ttyS5</td><td>PX4IO/RC</td></tr><tr><td>UART7</td><td>/dev/ttyS6</td><td>TELEM1</td></tr><tr><td>UART8</td><td>/dev/ttyS7</td><td>GPS2</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The mapping above applies to the running PX4 firmware. The ARKV6S bootloader enables only <code>UART7</code> (TELEM1), so when flashing firmware over UART with <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/px4_uploader.py" target="_blank" rel="noreferrer"><code>px4_uploader.py</code></a> you must connect to the <code>TELEM1</code> port — no other UART will respond in bootloader mode.</p></div><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ark_fmu-v6s_default</span></span></code></pre></div><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="https://arkelectron.gitbook.io/ark-documentation/flight-controllers/arkv6s" target="_blank" rel="noreferrer">ARK Electronics ARKV6S</a> (ARK Docs)</li></ul>',27)])])}const f=a(i,[["render",s]]);export{b as __pageData,f as default};
